import { QuizQuestion } from '@/types';

export const quizQuestions: QuizQuestion[] = [
  // ── MODULE 1 : Les 4 Nobles Vérités ──────────────────────────
  { id: 'q1-1', moduleId: 1, difficulty: 'facile', question: 'Combien y a-t-il de Nobles Vérités dans le bouddhisme ?', options: ['Deux', 'Quatre', 'Six', 'Huit'], correctAnswer: 1, explanation: 'Le Bouddha a enseigné quatre Nobles Vérités lors de son premier discours à Sarnath.', source: 'Dhammacakkappavattana Sutta, SN 56.11' },
  { id: 'q1-2', moduleId: 1, difficulty: 'facile', question: 'Que signifie le terme pali "Dukkha" ?', options: ['Bonheur', 'Souffrance / insatisfaction', 'Karma', 'Impermanence'], correctAnswer: 1, explanation: 'Dukkha désigne la souffrance, l\'insatisfaction ou la nature insatisfaisante de l\'existence conditionnée.', source: 'Dhammapada' },
  { id: 'q1-3', moduleId: 1, difficulty: 'facile', question: 'Quelle est la deuxième Noble Vérité ?', options: ['La cessation de la souffrance', 'L\'origine de la souffrance', 'Le chemin vers la libération', 'La nature de l\'impermanence'], correctAnswer: 1, explanation: 'Samudaya (l\'origine) est la deuxième Noble Vérité : le désir (tanha) est la cause de la souffrance.', source: 'Dhammacakkappavattana Sutta' },
  { id: 'q1-4', moduleId: 1, difficulty: 'facile', question: 'Comment s\'appelle la troisième Noble Vérité, la cessation de la souffrance ?', options: ['Magga', 'Samudaya', 'Nirodha', 'Dukkha'], correctAnswer: 2, explanation: 'Nirodha signifie "cessation" — la cessation complète du désir menant au Nirvana.', source: 'Dhammacakkappavattana Sutta' },
  { id: 'q1-5', moduleId: 1, difficulty: 'facile', question: 'Quel terme désigne le chemin vers la libération (quatrième Noble Vérité) ?', options: ['Nirodha', 'Magga', 'Tanha', 'Avijja'], correctAnswer: 1, explanation: 'Magga, le Noble Chemin Octuple, est la quatrième Noble Vérité.', source: 'Dhammacakkappavattana Sutta' },
  { id: 'q1-6', moduleId: 1, difficulty: 'facile', question: 'Quelles sont les trois marques (caractéristiques) de l\'existence ?', options: ['Dukkha, Karma, Nirvana', 'Anicca, Dukkha, Anatta', 'Metta, Karuna, Upekkha', 'Sila, Samadhi, Prajna'], correctAnswer: 1, explanation: 'Les trois marques (tilakkhana) sont : Anicca (impermanence), Dukkha (souffrance), Anatta (non-soi).', source: 'Dhammapada 277-279' },
  { id: 'q1-7', moduleId: 1, difficulty: 'facile', question: 'Tanha, cause de la souffrance, se traduit le mieux par :', options: ['Sagesse', 'Soif / désir', 'Compassion', 'Méditation'], correctAnswer: 1, explanation: 'Tanha signifie "soif" ou "désir" — c\'est la cause directe de la souffrance selon la deuxième Noble Vérité.', source: 'Dhammacakkappavattana Sutta' },
  { id: 'q1-8', moduleId: 1, difficulty: 'moyen', question: 'Quelles sont les trois formes de tanha (désir) identifiées par le Bouddha ?', options: ['Lobha, Dosa, Moha', 'Kama-tanha, Bhava-tanha, Vibhava-tanha', 'Raga, Dosa, Avijja', 'Sila, Samadhi, Prajna'], correctAnswer: 1, explanation: 'Le désir sensoriel (kama-tanha), le désir d\'existence (bhava-tanha) et le désir de non-existence (vibhava-tanha).', source: 'Dhammacakkappavattana Sutta, SN 56.11' },
  { id: 'q1-9', moduleId: 1, difficulty: 'moyen', question: 'Que désigne le terme "sankhara-dukkha" ?', options: ['La souffrance physique ordinaire', 'La souffrance du changement', 'La souffrance existentielle liée aux agrégats conditionnés', 'La souffrance causée par les autres'], correctAnswer: 2, explanation: 'Sankhara-dukkha est la souffrance existentielle fondamentale, liée à l\'attachement aux cinq agrégats conditionnés.', source: 'Sutta Pitaka' },
  { id: 'q1-10', moduleId: 1, difficulty: 'moyen', question: 'Combien d\'agrégats (khandhas) composent l\'être selon le Bouddha ?', options: ['Trois', 'Quatre', 'Cinq', 'Sept'], correctAnswer: 2, explanation: 'Les cinq agrégats (pancakkhandha) sont : forme, sensation, perception, formations mentales et conscience.', source: 'Anattalakkhana Sutta, SN 22.59' },
  { id: 'q1-11', moduleId: 1, difficulty: 'moyen', question: 'Le premier discours du Bouddha à Sarnath s\'appelle :', options: ['Satipatthana Sutta', 'Dhammacakkappavattana Sutta', 'Metta Sutta', 'Anattalakkhana Sutta'], correctAnswer: 1, explanation: 'Le Dhammacakkappavattana Sutta ("la mise en mouvement de la roue du Dhamma") est le premier discours.', source: 'SN 56.11' },
  { id: 'q1-12', moduleId: 1, difficulty: 'moyen', question: 'Qu\'est-ce que le Nirvana selon le bouddhisme Theravada ?', options: ['Un paradis céleste', 'L\'extinction du désir, de la haine et de l\'ignorance', 'La réincarnation dans une vie meilleure', 'Un état de transe profonde'], correctAnswer: 1, explanation: 'Le Nirvana est l\'extinction (nibbuta) des trois poisons : désir (lobha), haine (dosa) et ignorance (moha).', source: 'Udana 8.3' },
  { id: 'q1-13', moduleId: 1, difficulty: 'moyen', question: 'Quelle est la différence entre sa-upadisesa-nibbana et parinibbana ?', options: ['Aucune différence', 'Le premier est atteint de son vivant, le second à la mort', 'Le premier est pour les moines, le second pour les laïcs', 'Le premier est Mahayana, le second Theravada'], correctAnswer: 1, explanation: 'Sa-upadisesa-nibbana est le Nirvana avec résidu atteint du vivant ; parinibbana est le Nirvana sans résidu à la mort.', source: 'Itivuttaka' },
  { id: 'q1-14', moduleId: 1, difficulty: 'moyen', question: 'Que désigne "viparinama-dukkha" ?', options: ['La souffrance des êtres en enfer', 'La souffrance causée par le changement des situations agréables', 'La souffrance du non-soi', 'La souffrance de la méditation'], correctAnswer: 1, explanation: 'Viparinama-dukkha est la souffrance du changement : même les plaisirs causent de la souffrance car ils sont transitoires.', source: 'Sutta Pitaka' },
  { id: 'q1-15', moduleId: 1, difficulty: 'moyen', question: 'Où le Bouddha a-t-il prononcé son premier discours ?', options: ['Bodhgaya', 'Lumbini', 'Sarnath (Isipatana)', 'Kushinagar'], correctAnswer: 2, explanation: 'Le premier discours fut prononcé au Parc des Gazelles d\'Isipatana, près de Sarnath, devant cinq ascètes.', source: 'Dhammacakkappavattana Sutta' },
  { id: 'q1-16', moduleId: 1, difficulty: 'difficile', question: 'Dans le Udana 8.3, le Bouddha décrit le Nirvana comme :', options: ['Un état de pure conscience', 'Un non-né, non-devenu, non-créé, non-conditionné', 'L\'union avec le Brahman universel', 'Un vide absolu sans conscience'], correctAnswer: 1, explanation: '"Il y a, moines, un non-né, non-devenu, non-créé, non-conditionné" — Udana 8.3.', source: 'Udana 8.3' },
  { id: 'q1-17', moduleId: 1, difficulty: 'difficile', question: 'La chaîne de causalité paticca-samuppada commence par quel maillon ?', options: ['Tanha (désir)', 'Avijja (ignorance)', 'Vinnana (conscience)', 'Sankhara (formations)'], correctAnswer: 1, explanation: 'Avijja (ignorance) est le premier maillon qui conditionne tous les autres dans la chaîne des douze liens.', source: 'Assutava Sutta, SN 12.2' },
  { id: 'q1-18', moduleId: 1, difficulty: 'difficile', question: 'La formule classique de paticca-samuppada est :', options: ['"Si cela existe, cela existe toujours"', '"Ceci étant, cela est ; ceci naissant, cela naît"', '"Tout est un, un est tout"', '"Le désir crée la souffrance, la sagesse crée la paix"'], correctAnswer: 1, explanation: '"Imasming sati idam hoti" — "Ceci étant, cela est ; ceci naissant, cela naît" est la formule classique.', source: 'SN 12.2' },
  { id: 'q1-19', moduleId: 1, difficulty: 'difficile', question: 'Quel texte contient la première exposition complète des Quatre Nobles Vérités ?', options: ['Dhammapada', 'Dhammacakkappavattana Sutta', 'Satipatthana Sutta', 'Majjhima Nikaya'], correctAnswer: 1, explanation: 'Le Dhammacakkappavattana Sutta (SN 56.11) est le premier discours où les Quatre Nobles Vérités sont exposées.', source: 'SN 56.11' },
  { id: 'q1-20', moduleId: 1, difficulty: 'difficile', question: 'Selon le Bouddha, quel est le rapport entre voir paticca-samuppada et voir le Dhamma ?', options: ['Ce sont deux choses séparées', 'Voir l\'un c\'est voir l\'autre', 'Paticca-samuppada est plus profond', 'Le Dhamma est plus important'], correctAnswer: 1, explanation: '"Qui voit la production interdépendante voit le Dhamma ; qui voit le Dhamma voit la production interdépendante."', source: 'Mahatanha-sankaya Sutta, MN 38' },

  // ── MODULE 2 : Le Noble Chemin Octuple ───────────────────────
  { id: 'q2-1', moduleId: 2, difficulty: 'facile', question: 'Combien de facteurs compose le Noble Chemin Octuple ?', options: ['Quatre', 'Six', 'Huit', 'Dix'], correctAnswer: 2, explanation: 'Le Noble Chemin Octuple (Ariya Atthangika Magga) comprend exactement huit facteurs.', source: 'Dhammacakkappavattana Sutta' },
  { id: 'q2-2', moduleId: 2, difficulty: 'facile', question: 'Sammā-Diṭṭhi désigne :', options: ['La juste méditation', 'La juste vue', 'La juste parole', 'L\'juste action'], correctAnswer: 1, explanation: 'Sammā-diṭṭhi est la Juste Vue — comprendre les Quatre Nobles Vérités et la nature de la réalité.', source: 'Sacca-vibhanga Sutta, MN 141' },
  { id: 'q2-3', moduleId: 2, difficulty: 'facile', question: 'Quel groupe du Noble Chemin Octuple concerne l\'éthique (Sila) ?', options: ['Vue, Intention, Effort', 'Parole, Action, Moyen d\'existence', 'Effort, Attention, Concentration', 'Vue, Méditation, Sagesse'], correctAnswer: 1, explanation: 'Le groupe Sila (éthique) comprend Sammā-vācā (parole), Sammā-kammanta (action) et Sammā-ājīva (moyen d\'existence).', source: 'Sacca-vibhanga Sutta' },
  { id: 'q2-4', moduleId: 2, difficulty: 'facile', question: 'Sammā-Samādhi désigne :', options: ['La juste parole', 'La juste concentration', 'Le juste effort', 'La juste action'], correctAnswer: 1, explanation: 'Sammā-samādhi est la Juste Concentration, désignant les quatre jhanas de l\'absorption méditative.', source: 'Samaññaphala Sutta, DN 2' },
  { id: 'q2-5', moduleId: 2, difficulty: 'facile', question: 'Le Noble Chemin Octuple est symbolisé par :', options: ['Un lotus à huit pétales', 'Une roue à huit rayons', 'Un arbre à huit branches', 'Une étoile à huit branches'], correctAnswer: 1, explanation: 'La Roue du Dhamma (dhammacakka) à huit rayons symbolise le Noble Chemin Octuple.', source: 'Tradition bouddhiste' },
  { id: 'q2-6', moduleId: 2, difficulty: 'facile', question: 'Quelles sont les trois intentions de Sammā-sankappa ?', options: ['Générosité, éthique, méditation', 'Renoncement, bienveillance, non-nuisance', 'Foi, effort, sagesse', 'Calme, attention, équanimité'], correctAnswer: 1, explanation: 'Sammā-sankappa comprend : renoncement (nekkhamma), absence de malveillance (abyapada) et non-nuisance (avihimsa).', source: 'Sacca-vibhanga Sutta, MN 141' },
  { id: 'q2-7', moduleId: 2, difficulty: 'facile', question: 'Le Juste Moyen d\'Existence (Sammā-ājīva) interdit quel type de commerce ?', options: ['Le commerce agricole', 'Le commerce d\'armes et d\'êtres vivants', 'Le commerce d\'artisanat', 'Le commerce de tissus'], correctAnswer: 1, explanation: 'Sammā-ājīva interdit : commerce d\'armes, d\'êtres vivants, de viandes, de poisons et d\'intoxicants.', source: 'Sacca-vibhanga Sutta' },
  { id: 'q2-8', moduleId: 2, difficulty: 'moyen', question: 'Quels sont les quatre Grands Efforts (sammappadhana) de Sammā-vāyāma ?', options: ['Écouter, étudier, méditer, réaliser', 'Prévenir, abandonner, cultiver, maintenir', 'Donner, protéger, enseigner, pratiquer', 'Voir, comprendre, agir, libérer'], correctAnswer: 1, explanation: 'Les quatre efforts : prévenir les états non-salutaires, abandonner ceux présents, cultiver les salutaires, maintenir ceux présents.', source: 'Vibhanga Sutta, SN 45.8' },
  { id: 'q2-9', moduleId: 2, difficulty: 'moyen', question: 'Quels sont les quatre fondements de la pleine conscience (satipatthana) ?', options: ['Corps, sensations, conscience, phénomènes mentaux', 'Respiration, posture, marche, alimentation', 'Metta, Karuna, Mudita, Upekkha', 'Vue, intention, parole, action'], correctAnswer: 0, explanation: 'Les quatre fondements : kayanupassana (corps), vedananupassana (sensations), cittanupassana (conscience), dhammanupassana (phénomènes).', source: 'Satipatthana Sutta, MN 10' },
  { id: 'q2-10', moduleId: 2, difficulty: 'moyen', question: 'Le premier jhana est caractérisé par :', options: ['L\'équanimité pure sans joie ni douleur', 'Pensée dirigée, examen, joie et bonheur', 'Seulement joie et bonheur sans pensée', 'Ni joie ni douleur, seulement concentration'], correctAnswer: 1, explanation: 'Le premier jhana comprend vitakka (pensée dirigée), vicara (examen), piti (joie) et sukha (bonheur).', source: 'Samaññaphala Sutta, DN 2' },
  { id: 'q2-11', moduleId: 2, difficulty: 'moyen', question: 'Sammā-Sati est enseignée dans quel sutta célèbre ?', options: ['Dhammapada', 'Satipatthana Sutta (MN 10)', 'Anapanasati Sutta', 'Metta Sutta'], correctAnswer: 1, explanation: 'Le Satipatthana Sutta (MN 10) est le texte de référence pour Sammā-sati (la pleine conscience juste).', source: 'MN 10' },
  { id: 'q2-12', moduleId: 2, difficulty: 'moyen', question: 'Le Noble Chemin Octuple est appelé "chemin du milieu" car :', options: ['Il se situe entre Theravada et Mahayana', 'Il évite l\'indulgence aux plaisirs et l\'ascétisme sévère', 'Il convient à tous les niveaux spirituels', 'Il dure exactement huit mois'], correctAnswer: 1, explanation: 'Le "chemin du milieu" évite les deux extrêmes : l\'indulgence aux plaisirs sensoriels et l\'ascétisme sévère.', source: 'Dhammacakkappavattana Sutta' },
  { id: 'q2-13', moduleId: 2, difficulty: 'moyen', question: 'Quels facteurs composent le groupe Samadhi du Noble Chemin ?', options: ['Vue, Intention, Sagesse', 'Effort juste, Pleine conscience, Concentration juste', 'Parole, Action, Moyen d\'existence', 'Foi, Éthique, Générosité'], correctAnswer: 1, explanation: 'Le groupe Samadhi comprend Sammā-vāyāma (effort), Sammā-sati (pleine conscience) et Sammā-samādhi (concentration).', source: 'Sacca-vibhanga Sutta' },
  { id: 'q2-14', moduleId: 2, difficulty: 'moyen', question: 'Quels états mentaux sont appelés "nivaranas" (empêchements méditatifs) ?', options: ['Joie, calme, équanimité, attention, sagesse', 'Désir sensoriel, malveillance, torpeur, agitation, doute', 'Générosité, éthique, patience, énergie, concentration', 'Impermanence, souffrance, non-soi, interdépendance, karma'], correctAnswer: 1, explanation: 'Les cinq nivaranas sont : désir sensoriel, malveillance, torpeur-somnolence, agitation-remords, doute.', source: 'Satipatthana Sutta' },
  { id: 'q2-15', moduleId: 2, difficulty: 'moyen', question: 'Quelle est la caractéristique principale du quatrième jhana ?', options: ['Joie intense et bonheur', 'Absence de pensées dirigées', 'Pureté de l\'équanimité et de l\'attention', 'Perception de lumière intense'], correctAnswer: 2, explanation: 'Le quatrième jhana est caractérisé par la pureté de l\'équanimité (upekkha) et de l\'attention (sati) — ni plaisir ni douleur.', source: 'Samaññaphala Sutta, DN 2' },
  { id: 'q2-16', moduleId: 2, difficulty: 'difficile', question: 'Dans le Satipatthana Sutta, quelle phrase introduit l\'enseignement comme "voie unique" ?', options: ['Ekacitta, bhikkhave, maggo', 'Ekayano ayam, bhikkhave, maggo', 'Ekasila, bhikkhave, dhammo', 'Ekadhamma, bhikkhave, nibbano'], correctAnswer: 1, explanation: '"Ekayano ayam, bhikkhave, maggo" — "Il y a, moines, ce chemin unique" ouvre le Satipatthana Sutta.', source: 'Satipatthana Sutta, MN 10' },
  { id: 'q2-17', moduleId: 2, difficulty: 'difficile', question: 'Sammā-vācā inclut quatre abstentions. Laquelle n\'en fait PAS partie ?', options: ['S\'abstenir du mensonge', 'S\'abstenir de la parole divisive', 'S\'abstenir du chant et de la danse', 'S\'abstenir du bavardage inutile'], correctAnswer: 2, explanation: 'Les quatre abstentions de Sammā-vācā sont : mensonge, parole divisive, paroles dures, bavardage inutile.', source: 'Sacca-vibhanga Sutta, MN 141' },
  { id: 'q2-18', moduleId: 2, difficulty: 'difficile', question: 'Que désigne le terme pali "vitakka" dans le contexte du premier jhana ?', options: ['La joie méditatiive', 'La pensée ou attention dirigée vers l\'objet', 'La cessation de toute pensée', 'Le bonheur physique'], correctAnswer: 1, explanation: 'Vitakka désigne la pensée initiale dirigée vers l\'objet de méditation, caractéristique du premier jhana.', source: 'Samaññaphala Sutta, DN 2' },
  { id: 'q2-19', moduleId: 2, difficulty: 'difficile', question: 'Les quatre arupa-jhanas (absorptions immatérielles) commencent par :', options: ['L\'espace infini (akasanancayatana)', 'La conscience infinie (vinnanancayatana)', 'Le plan du néant (akincannayatana)', 'Le plan de ni-perception-ni-non-perception'], correctAnswer: 0, explanation: 'Le premier arupa-jhana est la sphère de l\'espace infini (akasanancayatana), suivi des trois autres.', source: 'Samaññaphala Sutta, DN 2' },
  { id: 'q2-20', moduleId: 2, difficulty: 'difficile', question: 'La formule de Sammā-diṭṭhi dans le Sacca-vibhanga Sutta est :', options: ['La connaissance des dieux', 'La connaissance du Dhamma par inférence', 'La connaissance de la souffrance, de son origine, de sa cessation, du chemin', 'La connaissance des vies passées'], correctAnswer: 2, explanation: 'Sammā-diṭṭhi est définie comme la connaissance de dukkha, samudaya, nirodha et magga — les Quatre Nobles Vérités.', source: 'Sacca-vibhanga Sutta, MN 141' },

  // ── MODULE 3 : Bouddha et son Éveil ──────────────────────────
  { id: 'q3-1', moduleId: 3, difficulty: 'facile', question: 'Où est né Siddhartha Gautama ?', options: ['Bodhgaya, Inde', 'Sarnath, Inde', 'Lumbini, Népal actuel', 'Kushinagar, Inde'], correctAnswer: 2, explanation: 'Siddhartha Gautama naquit à Lumbini, dans l\'actuel Népal, fils du roi Suddhodana.', source: 'Tradition bouddhiste' },
  { id: 'q3-2', moduleId: 3, difficulty: 'facile', question: 'Quel est le nom du père de Siddhartha Gautama ?', options: ['Ananda', 'Suddhodana', 'Devadatta', 'Rahula'], correctAnswer: 1, explanation: 'Le père de Siddhartha était le roi Suddhodana, chef du clan des Shakyas.', source: 'Tradition bouddhiste' },
  { id: 'q3-3', moduleId: 3, difficulty: 'facile', question: 'Sous quel arbre le Bouddha atteignit-il l\'éveil ?', options: ['Palmier', 'Manguier', 'Figuier (Ficus religiosa)', 'Arbre sala'], correctAnswer: 2, explanation: 'Le Bouddha s\'éveilla sous un Ficus religiosa, appelé depuis "arbre de la Bodhi" (arbre de l\'éveil).', source: 'Tradition bouddhiste' },
  { id: 'q3-4', moduleId: 3, difficulty: 'facile', question: 'Que signifie le mot "Bouddha" ?', options: ['Saint', 'Dieu', 'L\'Éveillé', 'Le Bienheureux'], correctAnswer: 2, explanation: 'Bouddha vient de la racine "budh" et signifie "l\'Éveillé" ou "Celui qui a compris".', source: 'Etymologie pali' },
  { id: 'q3-5', moduleId: 3, difficulty: 'facile', question: 'Quel est le nom du fils du Bouddha ?', options: ['Ananda', 'Devadatta', 'Rahula', 'Sariputta'], correctAnswer: 2, explanation: 'Rahula était le fils de Siddhartha et Yashodhara. Il devint moine et est mentionné dans plusieurs suttas.', source: 'Tradition bouddhiste' },
  { id: 'q3-6', moduleId: 3, difficulty: 'facile', question: 'Combien d\'années le Bouddha a-t-il enseigné après son éveil ?', options: ['15 ans', '25 ans', '45 ans', '60 ans'], correctAnswer: 2, explanation: 'Le Bouddha enseigna pendant 45 ans après son éveil, parcourant le nord de l\'Inde.', source: 'Tradition bouddhiste' },
  { id: 'q3-7', moduleId: 3, difficulty: 'facile', question: 'Comment s\'appelle la mort finale du Bouddha ?', options: ['Nirvana', 'Parinirvana', 'Mahasamadhi', 'Moksha'], correctAnswer: 1, explanation: 'Le parinirvana désigne la "mort finale" du Bouddha, son extinction définitive hors du cycle des renaissances.', source: 'Mahaparinibbana Sutta, DN 16' },
  { id: 'q3-8', moduleId: 3, difficulty: 'moyen', question: 'Quelles sont les "quatre rencontres" qui éveillèrent Siddhartha ?', options: ['Un maître, un moine, un saint, un sage', 'Un vieillard, un malade, un mort, un ascète', 'Un mendiant, un roi, un guerrier, un marchand', 'Un enfant, un adulte, un vieux, un moine'], correctAnswer: 1, explanation: 'Les quatre rencontres (cattaro nimitta) : un vieillard, un malade, un cadavre et un ascète pacifique.', source: 'Ariyapariyesana Sutta, MN 26' },
  { id: 'q3-9', moduleId: 3, difficulty: 'moyen', question: 'Avec quels maîtres Siddhartha étudia-t-il avant son éveil ?', options: ['Devadatta et Kondanna', 'Alara Kalama et Uddaka Ramaputta', 'Sariputta et Moggallana', 'Ananda et Kassapa'], correctAnswer: 1, explanation: 'Siddhartha étudia avec Alara Kalama (akincannayatana) puis Uddaka Ramaputta (nevasannanasannayatana).', source: 'Ariyapariyesana Sutta, MN 26' },
  { id: 'q3-10', moduleId: 3, difficulty: 'moyen', question: 'Qui était Sujata dans l\'histoire du Bouddha ?', options: ['La mère du Bouddha', 'La femme du Bouddha', 'La villageoise qui offrit du riz au lait avant l\'éveil', 'La première nonne bouddhiste'], correctAnswer: 2, explanation: 'Sujata était la villageoise qui offrit du riz au lait à Siddhartha, marquant l\'abandon des austérités extrêmes.', source: 'Tradition bouddhiste' },
  { id: 'q3-11', moduleId: 3, difficulty: 'moyen', question: 'Que représente Mara dans la tradition bouddhiste ?', options: ['Le dieu créateur', 'Le dieu de la mort, du désir et de l\'illusion', 'Un gardien de temple', 'Un disciple du Bouddha'], correctAnswer: 1, explanation: 'Mara symbolise les forces du désir, de la mort et de l\'illusion qui s\'opposent à l\'éveil.', source: 'Tradition bouddhiste' },
  { id: 'q3-12', moduleId: 3, difficulty: 'moyen', question: 'Quels sont les cinq premiers disciples qui reçurent le premier enseignement ?', options: ['Sariputta, Moggallana, Ananda, Rahula, Kassapa', 'Kondanna, Bhaddiya, Vappa, Mahanama, Assaji', 'Devadatta, Ananda, Nanda, Tissa, Upali', 'Ananda, Kassapa, Upali, Anuruddha, Rahula'], correctAnswer: 1, explanation: 'Les cinq premiers disciples étaient Kondanna, Bhaddiya, Vappa, Mahanama et Assaji — anciens compagnons d\'ascèse.', source: 'Dhammacakkappavattana Sutta, SN 56.11' },
  { id: 'q3-13', moduleId: 3, difficulty: 'moyen', question: 'Où le Bouddha prononça-t-il son parinirvana (mourut-il) ?', options: ['Bodhgaya', 'Sarnath', 'Rajgir', 'Kusinara (Kushinagar)'], correctAnswer: 3, explanation: 'Le Bouddha s\'éteignit à Kusinara (actuelle Kushinagar), allongé entre deux arbres sala.', source: 'Mahaparinibbana Sutta, DN 16' },
  { id: 'q3-14', moduleId: 3, difficulty: 'moyen', question: 'Quelles furent les dernières paroles du Bouddha ?', options: ['"Tout est illusion"', '"Allez, enseignez le Dharma"', '"Tous les composés sont impermanents. Avancez avec ardeur."', '"Le Nirvana est la seule réalité"'], correctAnswer: 2, explanation: '"Vayadhamma sankhara, appamadena sampadetha" — "Tous les composés sont impermanents. Avancez avec ardeur."', source: 'Mahaparinibbana Sutta, DN 16' },
  { id: 'q3-15', moduleId: 3, difficulty: 'moyen', question: 'La "Grande Renonciation" de Siddhartha eut lieu à quel âge ?', options: ['À 16 ans', 'À 29 ans', 'À 35 ans', 'À 45 ans'], correctAnswer: 1, explanation: 'Siddhartha quitta le palais, sa femme et son fils à l\'âge de 29 ans lors de la Grande Renonciation.', source: 'Tradition bouddhiste' },
  { id: 'q3-16', moduleId: 3, difficulty: 'difficile', question: 'Lors de la nuit de l\'éveil, quelle connaissance le Bouddha obtint-il lors de la première veille ?', options: ['Les Quatre Nobles Vérités', 'La connaissance des vies passées (pubbenivasa-ñana)', 'La loi du karma', 'La nature du non-soi'], correctAnswer: 1, explanation: 'Première veille : pubbenivasa-ñana, la connaissance des vies passées innombrables.', source: 'Tradition bouddhiste' },
  { id: 'q3-17', moduleId: 3, difficulty: 'difficile', question: 'Quel dieu intervint pour convaincre le Bouddha d\'enseigner après son éveil ?', options: ['Indra', 'Mara', 'Brahma Sahampati', 'Vishnu'], correctAnswer: 2, explanation: 'Brahma Sahampati supplia le Bouddha d\'enseigner, arguant qu\'il y a des êtres "aux yeux peu couverts de poussière".', source: 'Ariyapariyesana Sutta, MN 26' },
  { id: 'q3-18', moduleId: 3, difficulty: 'difficile', question: 'Combien de liens (samyojanas) le Bouddha brisa-t-il lors de l\'éveil ?', options: ['Cinq', 'Sept', 'Dix', 'Douze'], correctAnswer: 2, explanation: 'Le Bouddha brisa les dix liens (samyojanas) qui enchaînent au samsara.', source: 'Tradition Theravada' },
  { id: 'q3-19', moduleId: 3, difficulty: 'difficile', question: 'Le premier vers du Dhammapada (153) est associé à quel moment de la vie du Bouddha ?', options: ['Son départ du palais', 'Le moment de son éveil', 'Son premier discours', 'Son parinirvana'], correctAnswer: 1, explanation: '"Anekajatisamsaram sandhavissam..." — ce vers fut prononcé au moment de l\'éveil, s\'adressant à Mara/le constructeur.', source: 'Dhammapada 153-154' },
  { id: 'q3-20', moduleId: 3, difficulty: 'difficile', question: 'Que désigne le geste de "toucher la terre" (bhumi-sparsha mudra) du Bouddha ?', options: ['Un acte de prière à la déesse terre', 'Prendre la terre à témoin de ses mérites accumulés', 'Demander la pluie', 'Symboliser l\'enracinement dans la pratique'], correctAnswer: 1, explanation: 'Bhumi-sparsha mudra : le Bouddha toucha la terre pour la prendre à témoin de ses mérites, repoussant Mara.', source: 'Tradition bouddhiste' },

  // ── MODULE 4 : Bouddhisme Theravada ──────────────────────────
  { id: 'q4-1', moduleId: 4, difficulty: 'facile', question: 'Que signifie "Theravada" ?', options: ['La grande voie', 'L\'enseignement de l\'Ancien / la voie des Anciens', 'Le véhicule du diamant', 'La voie du milieu'], correctAnswer: 1, explanation: 'Theravada signifie "l\'enseignement des Anciens" (thera = ancien, vada = enseignement).', source: 'Etymologie pali' },
  { id: 'q4-2', moduleId: 4, difficulty: 'facile', question: 'Que signifie "Tipitaka" ?', options: ['Les trois joyaux', 'Les trois corbeilles', 'Les trois préceptes', 'Les trois terres pures'], correctAnswer: 1, explanation: 'Tipitaka signifie "Trois Corbeilles" (ti = trois, pitaka = corbeille) — le Canon Pali complet.', source: 'Tradition Theravada' },
  { id: 'q4-3', moduleId: 4, difficulty: 'facile', question: 'Quelles sont les trois corbeilles du Tipitaka ?', options: ['Dhamma, Sangha, Buddha', 'Vinaya, Sutta, Abhidhamma', 'Prajna, Karuna, Metta', 'Sila, Samadhi, Panna'], correctAnswer: 1, explanation: 'Les trois corbeilles du Tipitaka sont : Vinaya Pitaka, Sutta Pitaka et Abhidhamma Pitaka.', source: 'Canon Pali' },
  { id: 'q4-4', moduleId: 4, difficulty: 'facile', question: 'Combien de règles contient le Patimokkha pour les moines Theravada ?', options: ['108', '227', '365', '500'], correctAnswer: 1, explanation: 'Le Patimokkha contient 227 règles de discipline pour les moines (bhikkhus) du Theravada.', source: 'Vinaya Pitaka' },
  { id: 'q4-5', moduleId: 4, difficulty: 'facile', question: 'Vipassana signifie :', options: ['Calme mental', 'Vision pénétrante / claire voyance', 'Amour bienveillant', 'Absorption méditative'], correctAnswer: 1, explanation: 'Vipassana (vi + passana) signifie "voir clairement" ou "vision pénétrante" — la méditation d\'investigation.', source: 'Tradition Theravada' },
  { id: 'q4-6', moduleId: 4, difficulty: 'facile', question: 'Qui est un Sotapanna ?', options: ['Un moine qui a pris ses vœux', 'Celui qui est entré dans le courant vers l\'éveil', 'Un maître de méditation', 'Un novice bouddhiste'], correctAnswer: 1, explanation: 'Sotapanna (entré dans le courant) est le premier fruit de l\'éveil — il renaîtra au maximum sept fois.', source: 'Tradition Theravada' },
  { id: 'q4-7', moduleId: 4, difficulty: 'facile', question: 'Qu\'est-ce qu\'un Arahant ?', options: ['Un bodhisattva Mahayana', 'Un être libéré ayant détruit les dix liens', 'Un moine débutant', 'Un maître de la Terre Pure'], correctAnswer: 1, explanation: 'L\'Arahant est celui qui a détruit les dix liens et atteint la libération complète — plus de renaissances.', source: 'Khina Sutta, AN 3.87' },
  { id: 'q4-8', moduleId: 4, difficulty: 'moyen', question: 'Le Sutta Pitaka est divisé en cinq parties appelées :', options: ['Khandhas', 'Nikayas', 'Pitakas', 'Bhavanavaggas'], correctAnswer: 1, explanation: 'Le Sutta Pitaka est divisé en cinq nikayas : Digha, Majjhima, Samyutta, Anguttara et Khuddaka.', source: 'Canon Pali' },
  { id: 'q4-9', moduleId: 4, difficulty: 'moyen', question: 'Quelles sont les quatre offenses graves (parajika) entraînant l\'expulsion monastique ?', options: ['Mensonge, vol, violence, indécence', 'Relations sexuelles, vol, meurtre, fausse revendication de réalisations', 'Ivresse, querelle, désobéissance, absence', 'Abandonne robes, mange hors horaires, dort trop, parle trop'], correctAnswer: 1, explanation: 'Les quatre parajika : relations sexuelles, vol, meurtre d\'un humain, fausse revendication de réalisations spirituelles.', source: 'Vinaya Pitaka' },
  { id: 'q4-10', moduleId: 4, difficulty: 'moyen', question: 'L\'Abhidhamma catégorise combien de types de conscience (citta) ?', options: ['52', '28', '89', '121'], correctAnswer: 2, explanation: 'L\'Abhidhamma dénombre 89 types de conscience (ou 121 si on compte les variantes des jhanas).', source: 'Abhidhammatthasangaha' },
  { id: 'q4-11', moduleId: 4, difficulty: 'moyen', question: 'Quel est le texte de référence qui décrit les dix étapes de purification du chemin Theravada ?', options: ['Dhammapada', 'Visuddhimagga de Buddhaghosa', 'Milindapanha', 'Abhidhammatthasangaha'], correctAnswer: 1, explanation: 'Le Visuddhimagga (Ve s.) de Buddhaghosa décrit les dasa visuddhi — dix étapes de purification.', source: 'Visuddhimagga, Buddhaghosa' },
  { id: 'q4-12', moduleId: 4, difficulty: 'moyen', question: 'Qui est un Anagami dans la progression des fruits de l\'éveil ?', options: ['Celui qui a abandonné cinq liens et ne reviendra plus dans les mondes de désir', 'Celui qui revient une fois', 'Celui qui est entré dans le courant', 'Celui qui a atteint le Nirvana'], correctAnswer: 0, explanation: 'L\'Anagami ("non-retournant") a éliminé les cinq liens inférieurs et ne renaît plus dans les mondes de désir.', source: 'Tradition Theravada' },
  { id: 'q4-13', moduleId: 4, difficulty: 'moyen', question: 'Que désigne la "voie sèche" (sukkhavipassaka) en méditation Theravada ?', options: ['Méditer dans un climat chaud', 'Pratiquer vipassana sans développer préalablement les jhanas', 'Une technique de méditation debout', 'La méditation sur les éléments'], correctAnswer: 1, explanation: 'La "voie sèche" pratique directement vipassana sans le "lubrifiant" des jhanas de quiétude.', source: 'Tradition Theravada' },
  { id: 'q4-14', moduleId: 4, difficulty: 'moyen', question: 'Quelle est la pratique centrale de la méthode Mahasi Sayadaw ?', options: ['Observer la flamme d\'une bougie', 'Observer le mouvement de l\'abdomen avec notation mentale', 'Compter les respirations de 1 à 10', 'Visualiser la lumière dans le cœur'], correctAnswer: 1, explanation: 'Mahasi Sayadaw enseignait l\'observation du gonflement-dégonflement de l\'abdomen avec notation : "expansion", "contraction".', source: 'Tradition Mahasi Sayadaw' },
  { id: 'q4-15', moduleId: 4, difficulty: 'moyen', question: 'Dans quel pays le Tipitaka a-t-il été mis par écrit pour la première fois ?', options: ['Inde', 'Myanmar', 'Sri Lanka', 'Thaïlande'], correctAnswer: 2, explanation: 'Le Tipitaka fut mis par écrit au Sri Lanka lors du 4e Concile bouddhiste au 1er siècle av. J.-C.', source: 'Histoire du bouddhisme' },
  { id: 'q4-16', moduleId: 4, difficulty: 'difficile', question: 'Combien de facteurs mentaux (cetasika) l\'Abhidhamma identifie-t-il ?', options: ['28', '52', '89', '121'], correctAnswer: 1, explanation: 'L\'Abhidhamma Theravada identifie 52 cetasika (facteurs mentaux) qui se combinent avec la conscience.', source: 'Abhidhammatthasangaha' },
  { id: 'q4-17', moduleId: 4, difficulty: 'difficile', question: 'Quels sont les cinq liens supérieurs (pancorambhagiya-samyojana) abandonnés par l\'Arahant ?', options: ['Illusion du soi, doute, attachement aux rites, désir sensoriel, malveillance', 'Désir pour les mondes de forme, désir sans forme, orgueil, agitation, ignorance', 'Haine, jalousie, avarice, tromperie, hypocrisie', 'Foi, vertu, générosité, sagesse, honte morale'], correctAnswer: 1, explanation: 'Les cinq liens supérieurs : désir-forme (ruparaga), désir-sans-forme (aruparaga), orgueil (mana), agitation (uddhacca), ignorance (avijja).', source: 'Tradition Theravada' },
  { id: 'q4-18', moduleId: 4, difficulty: 'difficile', question: 'La "citta-vithi" (processus cognitif) de l\'Abhidhamma comprend combien de moments de conscience ?', options: ['7', '12', '17', '21'], correctAnswer: 2, explanation: 'La citta-vithi décrit un processus cognitif complet en 17 moments de conscience (cittas).', source: 'Abhidhammatthasangaha' },
  { id: 'q4-19', moduleId: 4, difficulty: 'difficile', question: 'Dans quelle tradition le moine S.N. Goenka s\'inscrit-il ?', options: ['Tradition Mahasi Sayadaw', 'Tradition de Sayagyi U Ba Khin', 'Tradition Pa-Auk Sayadaw', 'Tradition Ajahn Chah'], correctAnswer: 1, explanation: 'S.N. Goenka transmit la technique de vipassana de son maître birman Sayagyi U Ba Khin, centrée sur les sensations corporelles.', source: 'Tradition Goenka' },
  { id: 'q4-20', moduleId: 4, difficulty: 'difficile', question: 'Le Sakadagami se distingue du Sotapanna par :', options: ['Il a abandonné plus de liens', 'Il a affaibli (pas éliminé) le désir sensoriel et la malveillance et ne reviendra qu\'une fois', 'Il peut accéder aux jhanas', 'Il a reçu l\'ordination monastique'], correctAnswer: 1, explanation: 'Le Sakadagami (revenant-une-fois) a affaibli kama-raga et patigha, et reviendra dans le monde de désir une seule fois.', source: 'Tradition Theravada' },

  // ── MODULE 5 : Bouddhisme Mahayana ───────────────────────────
  { id: 'q5-1', moduleId: 5, difficulty: 'facile', question: 'Que signifie "Mahayana" ?', options: ['La petite voie', 'Le grand véhicule', 'La voie du diamant', 'La voie ancienne'], correctAnswer: 1, explanation: 'Mahayana signifie "Grand Véhicule" (maha = grand, yana = véhicule), par opposition au Hinayana.', source: 'Etymologie sanskrit' },
  { id: 'q5-2', moduleId: 5, difficulty: 'facile', question: 'Qu\'est-ce qu\'un bodhisattva ?', options: ['Un moine Theravada avancé', 'Un être qui aspire à l\'éveil complet pour le bien de tous les êtres', 'Un texte sacré Mahayana', 'Un type de méditation'], correctAnswer: 1, explanation: 'Un bodhisattva est un être qui génère la bodhicitta et aspire à la bouddhéité pour libérer tous les êtres.', source: 'Tradition Mahayana' },
  { id: 'q5-3', moduleId: 5, difficulty: 'facile', question: 'Que signifie "shunyata" ?', options: ['Bonheur', 'Compassion', 'Vacuité', 'Méditation'], correctAnswer: 2, explanation: 'Shunyata signifie "vacuité" — l\'absence d\'existence propre (svabhava) de tous les phénomènes.', source: 'Tradition Mahayana' },
  { id: 'q5-4', moduleId: 5, difficulty: 'facile', question: 'Quel philosophe bouddhiste est considéré comme le fondateur du Madhyamaka ?', options: ['Asanga', 'Vasubandhu', 'Nagarjuna', 'Chandrakirti'], correctAnswer: 2, explanation: 'Nagarjuna (IIe s. ap. J.-C.) fonda l\'école Madhyamaka et écrivit le Mulamadhyamakakarika.', source: 'Histoire du Mahayana' },
  { id: 'q5-5', moduleId: 5, difficulty: 'facile', question: 'Quelle est la phrase centrale du Sutra du Cœur ?', options: ['"Tout est Nirvana"', '"La forme est vacuité, la vacuité est forme"', '"Le désir est la cause de la souffrance"', '"Soyez une lumière pour vous-mêmes"'], correctAnswer: 1, explanation: '"Rupa shunyata, shunyata eva rupa" — "La forme est vacuité, la vacuité est forme" est la phrase centrale.', source: 'Prajnaparamita Hridaya Sutra' },
  { id: 'q5-6', moduleId: 5, difficulty: 'facile', question: 'Qu\'est-ce que le nembutsu dans la tradition de la Terre Pure ?', options: ['Une posture de méditation', 'La récitation du nom d\'Amitabha Buddha', 'Un texte sacré', 'Un rite funéraire'], correctAnswer: 1, explanation: 'Le nembutsu (namu amida butsu) est la récitation dévotionnelle du nom d\'Amitabha, pratique centrale de la Terre Pure.', source: 'Tradition Jodo' },
  { id: 'q5-7', moduleId: 5, difficulty: 'facile', question: 'Bodhidharma est considéré comme le fondateur de quelle école bouddhiste ?', options: ['Theravada', 'Terre Pure', 'Chan/Zen', 'Vajrayana'], correctAnswer: 2, explanation: 'Bodhidharma est le fondateur légendaire du Chan (Zen) en Chine au VIe siècle.', source: 'Tradition Zen' },
  { id: 'q5-8', moduleId: 5, difficulty: 'moyen', question: 'Quelles sont les six paramitas du bodhisattva ?', options: ['Foi, effort, sagesse, méditation, générosité, éthique', 'Générosité, éthique, patience, ardeur, méditation, sagesse', 'Joie, paix, compassion, équanimité, sagesse, méditation', 'Amour, vérité, pureté, non-violence, compassion, sagesse'], correctAnswer: 1, explanation: 'Les six paramitas : dana, sila, ksanti, virya, dhyana et prajna — générosité, éthique, patience, énergie, méditation, sagesse.', source: 'Tradition Mahayana' },
  { id: 'q5-9', moduleId: 5, difficulty: 'moyen', question: 'L\'école Yogacara est aussi appelée :', options: ['Madhyamaka', 'Cittamatra (esprit seul)', 'Prasangika', 'Svantantrika'], correctAnswer: 1, explanation: 'L\'école Yogacara, fondée par Asanga et Vasubandhu, est aussi appelée Cittamatra (l\'esprit seul est réel).', source: 'Histoire du Mahayana' },
  { id: 'q5-10', moduleId: 5, difficulty: 'moyen', question: 'Qu\'est-ce que la bodhicitta ?', options: ['L\'état d\'absorption profonde', 'L\'esprit d\'éveil, résolution d\'atteindre la bouddhéité pour tous les êtres', 'Un type de prière bouddhiste', 'Le livre sacré du Mahayana'], correctAnswer: 1, explanation: 'Bodhicitta ("esprit d\'éveil") est la résolution de l\'aspiration à l\'éveil complet pour le bénéfice de tous les êtres.', source: 'Tradition Mahayana' },
  { id: 'q5-11', moduleId: 5, difficulty: 'moyen', question: 'Le shikantaza est associé à quelle école Zen ?', options: ['Rinzai', 'Soto', 'Obaku', 'Linji'], correctAnswer: 1, explanation: 'Shikantaza ("simplement s\'asseoir") est la pratique centrale de l\'école Soto Zen, enseignée par Dogen Zenji.', source: 'Fukanzazengi, Dogen' },
  { id: 'q5-12', moduleId: 5, difficulty: 'moyen', question: 'Que désigne le terme "kensho" dans la tradition Zen ?', options: ['La posture de méditation', 'L\'aperçu ou la réalisation directe de la nature de Bouddha', 'Un type de koan', 'Le jardin de méditation zen'], correctAnswer: 1, explanation: 'Kensho (ou satori) désigne l\'aperçu direct de la nature de Bouddha, l\'expérience d\'éveil en Zen.', source: 'Tradition Zen' },
  { id: 'q5-13', moduleId: 5, difficulty: 'moyen', question: 'Sukhavati est :', options: ['Un koan Zen', 'La Terre Pure d\'Amitabha', 'Un état de méditation', 'Un concile bouddhiste'], correctAnswer: 1, explanation: 'Sukhavati ("Terre de Félicité") est la Terre Pure du Bouddha Amitabha, destination des dévots de l\'Amidisme.', source: 'Sukhavativyuha Sutra' },
  { id: 'q5-14', moduleId: 5, difficulty: 'moyen', question: 'Combien de terres progressives un bodhisattva traverse-t-il (dasabhumika) ?', options: ['Six', 'Eight', 'Dix', 'Douze'], correctAnswer: 2, explanation: 'Le dasabhumika décrit dix terres progressives (bhumis) du chemin du bodhisattva vers la bouddhéité complète.', source: 'Dasabhumika Sutra' },
  { id: 'q5-15', moduleId: 5, difficulty: 'moyen', question: 'Honen est associé à quelle école du Bouddhisme japonais ?', options: ['Jodo-shu (Terre Pure)', 'Zen Rinzai', 'Zen Soto', 'Shingon'], correctAnswer: 0, explanation: 'Honen (XIIe s.) fonda l\'école Jodo-shu (Terre Pure) au Japon, basée sur le nembutsu.', source: 'Histoire du bouddhisme japonais' },
  { id: 'q5-16', moduleId: 5, difficulty: 'difficile', question: 'La méthode prasanga (réfutation par conséquences absurdes) est propre à quelle école ?', options: ['Yogacara', 'Madhyamaka Prasangika', 'Zen', 'Terre Pure'], correctAnswer: 1, explanation: 'Le Madhyamaka Prasangika (Chandrakirti) utilise le prasanga pour réfuter toute position sans en établir une autre.', source: 'Madhyamaka, Nagarjuna/Chandrakirti' },
  { id: 'q5-17', moduleId: 5, difficulty: 'difficile', question: 'L\'apratisthita-nirvana du Mahayana désigne :', options: ['Le Nirvana des Arahants Theravada', 'Le Nirvana "sans résidence" du bodhisattva qui agit librement pour tous les êtres', 'Un état de méditation profonde', 'La mort du Bouddha historique'], correctAnswer: 1, explanation: 'Apratisthita-nirvana : le bodhisattva ne s\'installe ni dans le samsara ni dans le nirvana mais agit librement par compassion.', source: 'Tradition Mahayana' },
  { id: 'q5-18', moduleId: 5, difficulty: 'difficile', question: 'Shinran Shonin développa la Jodo Shinshu, distinguée de la Jodo-shu de Honen par :', options: ['Une pratique plus sévère', 'L\'accent sur shinjin (foi pure) et la confiance totale en la grâce d\'Amida', 'L\'ajout de pratiques méditatives', 'Le rejet du nembutsu'], correctAnswer: 1, explanation: 'Shinran insista sur shinjin (foi pure) : c\'est la compassion d\'Amida qui sauve, non nos propres mérites.', source: 'Tradition Jodo Shinshu' },
  { id: 'q5-19', moduleId: 5, difficulty: 'difficile', question: 'Le Fukanzazengi de Dogen commence par :', options: ['Un appel à l\'étude des textes', 'Un questionnement sur pourquoi on doit pratiquer', 'Une invitation à cesser de chercher des formules verbales', 'Une description des jhanas'], correctAnswer: 2, explanation: 'Fukanzazengi : "Vous devriez cesser de chercher des formules verbales et apprendre à reculer pour faire briller votre lumière."', source: 'Fukanzazengi, Dogen Zenji' },
  { id: 'q5-20', moduleId: 5, difficulty: 'difficile', question: 'La catuskoti (tétralemme) du Madhyamaka examine chaque proposition sous :', options: ['Deux aspects : vrai ou faux', 'Quatre aspects : est, n\'est pas, est et n\'est pas, ni est ni n\'est pas', 'Trois aspects : physique, mental, spirituel', 'Sept aspects selon Nagarjuna'], correctAnswer: 1, explanation: 'Le tétralemme examine : X est, X n\'est pas, X est et n\'est pas, X ni est ni n\'est pas — pour réfuter toute position fixe.', source: 'Mulamadhyamakakarika, Nagarjuna' },

  // ── MODULE 6 : Méditation et Pleine Conscience ───────────────
  { id: 'q6-1', moduleId: 6, difficulty: 'facile', question: 'Anapanasati signifie :', options: ['Méditation sur la mort', 'Pleine conscience de la respiration', 'Amour bienveillant', 'Méditation sur les sensations'], correctAnswer: 1, explanation: 'Anapanasati (ana = inspiration, apana = expiration, sati = pleine conscience) est la méditation sur la respiration.', source: 'Anapanasati Sutta, MN 118' },
  { id: 'q6-2', moduleId: 6, difficulty: 'facile', question: 'Que signifie "metta" ?', options: ['Sagesse', 'Amour bienveillant / bienveillance aimante', 'Équanimité', 'Pleine conscience'], correctAnswer: 1, explanation: 'Metta (pali) ou maitri (sanskrit) signifie amour bienveillant, bienveillance aimante.', source: 'Metta Sutta, Sn 1.8' },
  { id: 'q6-3', moduleId: 6, difficulty: 'facile', question: 'Combien de brahmaviharas (demeures divines) y a-t-il ?', options: ['Deux', 'Trois', 'Quatre', 'Six'], correctAnswer: 2, explanation: 'Les quatre brahmaviharas sont : metta (amour), karuna (compassion), mudita (joie partagée), upekkha (équanimité).', source: 'Tradition bouddhiste' },
  { id: 'q6-4', moduleId: 6, difficulty: 'facile', question: 'Zazen est la pratique méditative centrale de :', options: ['Theravada', 'Terre Pure', 'Zen', 'Vajrayana tibétain'], correctAnswer: 2, explanation: 'Zazen (méditation assise) est la pratique centrale du bouddhisme Zen, particulièrement l\'école Soto.', source: 'Tradition Zen' },
  { id: 'q6-5', moduleId: 6, difficulty: 'facile', question: 'Tonglen est une pratique méditative de :', options: ['La tradition Theravada', 'La tradition tibétaine (lojong)', 'La tradition Zen japonaise', 'La tradition Terre Pure'], correctAnswer: 1, explanation: 'Tonglen ("prendre et donner") est une pratique du lojong tibétain, popularisée par Pema Chödrön.', source: 'Tradition tibétaine' },
  { id: 'q6-6', moduleId: 6, difficulty: 'facile', question: 'Combien de facteurs d\'éveil (bojjhanga) y a-t-il ?', options: ['Quatre', 'Six', 'Sept', 'Huit'], correctAnswer: 2, explanation: 'Les sept facteurs d\'éveil (satta bojjhanga) : sati, dhammavicaya, viriya, piti, passaddhi, samadhi, upekkha.', source: 'Bojjhanga Sutta, SN 46.3' },
  { id: 'q6-7', moduleId: 6, difficulty: 'facile', question: 'La méditation metta commence par générer l\'amour envers :', options: ['Tous les êtres en même temps', 'Un ennemi pour travailler sur les résistances', 'Soi-même en premier', 'Un maître spirituel'], correctAnswer: 2, explanation: 'La tradition enseigne de commencer metta envers soi-même, base indispensable avant de l\'étendre aux autres.', source: 'Tradition bouddhiste' },
  { id: 'q6-8', moduleId: 6, difficulty: 'moyen', question: 'L\'Anapanasati Sutta organise la pratique en combien d\'étapes ?', options: ['Quatre', 'Huit', 'Seize', 'Vingt-et-un'], correctAnswer: 2, explanation: 'L\'Anapanasati Sutta (MN 118) décrit seize étapes organisées en quatre tétrades.', source: 'Anapanasati Sutta, MN 118' },
  { id: 'q6-9', moduleId: 6, difficulty: 'moyen', question: 'Quel est l\'"ennemi proche" de la compassion (karuna) ?', options: ['La haine', 'La douleur ou le désespoir', 'L\'indifférence', 'L\'amour possessif'], correctAnswer: 1, explanation: 'L\'"ennemi proche" de karuna est la douleur ou le désespoir — la compassion ne doit pas devenir accablement.', source: 'Tradition bouddhiste' },
  { id: 'q6-10', moduleId: 6, difficulty: 'moyen', question: 'Le Metta Sutta compare l\'amour bienveillant à :', options: ['La clarté du soleil', 'L\'amour d\'une mère pour son fils unique', 'La profondeur de l\'océan', 'La constance de la montagne'], correctAnswer: 1, explanation: '"Comme une mère protège de sa vie son enfant unique, que l\'on cultive un cœur d\'amour sans limite" — Metta Sutta.', source: 'Karaniya Metta Sutta, Sn 1.8' },
  { id: 'q6-11', moduleId: 6, difficulty: 'moyen', question: 'Le lojong tibétain comprend combien de slogans d\'entraînement de l\'esprit ?', options: ['21', '37', '59', '108'], correctAnswer: 2, explanation: 'Le lojong de Chekawa Yeshe Dorje comprend 59 slogans d\'entraînement de l\'esprit organisés en sept points.', source: 'Lojong, Chekawa Yeshe Dorje' },
  { id: 'q6-12', moduleId: 6, difficulty: 'moyen', question: 'Quelle qualité distingue samatha de vipassana ?', options: ['Samatha est assise, vipassana est debout', 'Samatha développe le calme/quiétude, vipassana développe la vision pénétrante', 'Samatha est Mahayana, vipassana est Theravada', 'Samatha est pour moines, vipassana pour laïcs'], correctAnswer: 1, explanation: 'Samatha développe le calme et la quiétude mentale ; vipassana développe la vision pénétrante de la réalité.', source: 'Tradition Theravada' },
  { id: 'q6-13', moduleId: 6, difficulty: 'moyen', question: 'Quand l\'esprit est somnolent en méditation, quels facteurs d\'éveil faut-il cultiver ?', options: ['Passaddhi, samadhi, upekkha', 'Dhammavicaya, viriya, piti', 'Sati, samadhi, upekkha', 'Piti, passaddhi, sati'], correctAnswer: 1, explanation: 'Pour contrer la somnolence : dhammavicaya (investigation), viriya (énergie) et piti (joie) sont énergisants.', source: 'Bojjhanga Sutta, SN 46.3' },
  { id: 'q6-14', moduleId: 6, difficulty: 'moyen', question: 'L\'enseignement du Metta Sutta (Sn 1.8) conclut avec :', options: ['Une invitation au Nirvana immédiat', 'Maintenir la pleine conscience en toutes postures — "c\'est la demeure divine"', 'Réciter le sutta trois fois par jour', 'Offrir des fleurs aux moines'], correctAnswer: 1, explanation: 'La conclusion du Metta Sutta : maintenir la pleine conscience debout, marchant, assis, couché — "demeure divine".', source: 'Karaniya Metta Sutta, Sn 1.8' },
  { id: 'q6-15', moduleId: 6, difficulty: 'moyen', question: 'Tonglen inverse quel principe habituel ?', options: ['La respiration naturelle', 'La tendance à chercher le plaisir et éviter la douleur', 'L\'ordre des mantras', 'La direction de la méditation assise'], correctAnswer: 1, explanation: 'Tonglen inverse la tendance habituelle : on prend la souffrance (inspire) et donne la joie (expire).', source: 'Tradition lojong tibétain' },
  { id: 'q6-16', moduleId: 6, difficulty: 'difficile', question: 'L\'Anapanasati Sutta affirme que la pratique accomplit les quatre fondements et les sept facteurs d\'éveil — quelle est la promesse finale ?', options: ['Rebirth in a Pure Land', 'L\'atteindre l\'éveil "ici et maintenant ou après la mort"', 'L\'obtention des jhanas', 'La vision des vies passées'], correctAnswer: 1, explanation: 'Le Bouddha promet dans MN 118 que l\'anapanasati accomplit les sept facteurs d\'éveil et mène au Nirvana.', source: 'Anapanasati Sutta, MN 118' },
  { id: 'q6-17', moduleId: 6, difficulty: 'difficile', question: 'Mudita, la troisième brahmavihara, se traduit par :', options: ['Équanimité', 'Compassion', 'Joie sympathique / joie partagée', 'Générosité'], correctAnswer: 2, explanation: 'Mudita est la joie sympathique ou joie partagée — se réjouir sincèrement du bonheur des autres.', source: 'Tradition bouddhiste' },
  { id: 'q6-18', moduleId: 6, difficulty: 'difficile', question: 'Le Bojjhanga Sutta affirme que les sept facteurs d\'éveil ont quel pouvoir surprenant ?', options: ['Générer de bons karmas', 'Guérir les maladies physiques', 'Attirer les bonnes renaissances', 'Purifier les péchés passés'], correctAnswer: 1, explanation: 'Le Bojjhanga Sutta (SN 46.16) raconte que la récitation des sept facteurs guérit des maladies graves.', source: 'Bojjhanga Sutta, SN 46.16' },
  { id: 'q6-19', moduleId: 6, difficulty: 'difficile', question: 'Dans la posture zazen décrite par Dogen, comment sont orientés les yeux ?', options: ['Fermés complètement', 'Ouverts grand vers le ciel', 'Mi-ouverts, regard vers le bas à 45 degrés', 'Fixés sur un point précis devant soi'], correctAnswer: 2, explanation: 'Dans zazen, les yeux sont mi-ouverts (half-open), regardant vers le bas à environ 45 degrés, ni complètement ouverts ni fermés.', source: 'Fukanzazengi, Dogen Zenji' },
  { id: 'q6-20', moduleId: 6, difficulty: 'difficile', question: 'Pema Chödrön est une enseignante de :', options: ['Bouddhisme Theravada thaïlandais', 'Tradition Shambhala/Vajrayana tibétain', 'Zen japonais', 'Bouddhisme engagé vietnamien'], correctAnswer: 1, explanation: 'Pema Chödrön est une enseignante de la tradition Shambhala fondée par Chogyam Trungpa Rinpoche — bouddhisme tibétain.', source: 'Tradition Shambhala' },

  // ── MODULE 7 : Karma et Renaissance ──────────────────────────
  { id: 'q7-1', moduleId: 7, difficulty: 'facile', question: 'Que signifie littéralement "karma" en sanskrit ?', options: ['Destin', 'Action', 'Souffrance', 'Renforcement'], correctAnswer: 1, explanation: 'Karma signifie littéralement "action" en sanskrit et pali. Il désigne les actions intentionnelles et leurs effets.', source: 'Etymologie sanskrit' },
  { id: 'q7-2', moduleId: 7, difficulty: 'facile', question: 'Samsara signifie :', options: ['Le Nirvana', 'La méditation profonde', 'Le cycle des morts et renaissances', 'La communauté monastique'], correctAnswer: 2, explanation: 'Samsara ("errance continue") est le cycle des renaissances conditionné par le karma et l\'ignorance.', source: 'Tradition bouddhiste' },
  { id: 'q7-3', moduleId: 7, difficulty: 'facile', question: 'Combien de royaumes d\'existence compte la cosmologie bouddhiste ?', options: ['Trois', 'Cinq', 'Six', 'Neuf'], correctAnswer: 2, explanation: 'La cosmologie bouddhiste décrit six royaumes : dieux, demi-dieux, humains, animaux, pretas, enfers.', source: 'Tradition bouddhiste' },
  { id: 'q7-4', moduleId: 7, difficulty: 'facile', question: 'Selon le Bouddha, qu\'est-ce que le karma en priorité ?', options: ['Une force cosmique impersonnelle', 'L\'intention (cetana) derrière l\'action', 'Le résultat des actions passées', 'La loi de la gravité spirituelle'], correctAnswer: 1, explanation: '"Cetana\'ham, bhikkhave, kammam vadami" — "C\'est l\'intention que j\'appelle karma." AN 6.63', source: 'Nibbedhika Sutta, AN 6.63' },
  { id: 'q7-5', moduleId: 7, difficulty: 'facile', question: 'Quelles sont les trois racines non-salutaires du karma ?', options: ['Ignorance, paresse, orgueil', 'Désir (lobha), haine (dosa), ignorance (moha)', 'Violence, mensonge, vol', 'Orgueil, jalousie, avarice'], correctAnswer: 1, explanation: 'Les trois racines non-salutaires (akusala-mula) sont lobha (désir), dosa (haine) et moha (ignorance).', source: 'Tradition bouddhiste' },
  { id: 'q7-6', moduleId: 7, difficulty: 'facile', question: 'Le Bardo Thodol est connu en Occident sous le nom de :', options: ['Le Livre Tibétain de la Méditation', 'Le Livre des Morts Tibétain', 'L\'Enseignement de Padmasambhava', 'La Voie du Milieu Tibétaine'], correctAnswer: 1, explanation: 'Bardo Thodol signifie "libération dans l\'état intermédiaire" — connu en Occident comme le "Livre des Morts Tibétain".', source: 'Tradition Vajrayana tibétain' },
  { id: 'q7-7', moduleId: 7, difficulty: 'facile', question: 'La roue du samsara (bhavacakra) est symboliquement tenue par :', options: ['Le Bouddha', 'Brahma', 'Mara', 'Un bodhisattva'], correctAnswer: 2, explanation: 'Mara (le dieu de la mort) tient la bhavacakra, symbolisant l\'emprise de l\'ignorance et du désir sur le cycle.', source: 'Tradition bouddhiste' },
  { id: 'q7-8', moduleId: 7, difficulty: 'moyen', question: 'Paticca-samuppada compte combien de liens causaux ?', options: ['Huit', 'Ten', 'Douze', 'Seize'], correctAnswer: 2, explanation: 'La production interdépendante (paticca-samuppada) comprend exactement douze liens, d\'avijja à jara-marana.', source: 'Assutava Sutta, SN 12' },
  { id: 'q7-9', moduleId: 7, difficulty: 'moyen', question: 'Les pretas dans la cosmologie bouddhiste sont :', options: ['Des dieux célestes', 'Des esprits affamés torturés par un désir insatiable', 'Des animaux mythologiques', 'Des êtres des enfers'], correctAnswer: 1, explanation: 'Les pretas (esprits affamés) sont des êtres aux ventres énormes et gorges minuscules, symboles de désir insatiable.', source: 'Tradition bouddhiste' },
  { id: 'q7-10', moduleId: 7, difficulty: 'moyen', question: 'Selon la tradition bouddhiste, quel royaume d\'existence est le plus favorable à l\'éveil ?', options: ['Le royaume des dieux', 'Le royaume humain', 'Le royaume des demi-dieux', 'Le premier ciel Brahma'], correctAnswer: 1, explanation: 'L\'existence humaine est la plus favorable car elle équilibre plaisir et souffrance, avec capacité de pratique spirituelle.', source: 'Tradition bouddhiste' },
  { id: 'q7-11', moduleId: 7, difficulty: 'moyen', question: 'Quel est le huitième lien de paticca-samuppada, point d\'intervention pratique ?', options: ['Avijja (ignorance)', 'Vinnana (conscience)', 'Tanha (désir)', 'Upadana (attachement)'], correctAnswer: 2, explanation: 'Tanha (désir) est le huitième lien — c\'est le point le plus accessible pour interrompre le cycle dans la pratique.', source: 'Sutta Pitaka' },
  { id: 'q7-12', moduleId: 7, difficulty: 'moyen', question: 'Combien de bardos identifie la tradition tibétaine ?', options: ['Deux', 'Quatre', 'Six', 'Huit'], correctAnswer: 2, explanation: 'La tradition tibétaine identifie six bardos : trois de la vie (vie, rêve, méditation) et trois de la mort (agonie, dharmata, devenir).', source: 'Bardo Thodol' },
  { id: 'q7-13', moduleId: 7, difficulty: 'moyen', question: 'La "Lumière Claire Primordiale" dans le Bardo Thodol représente :', options: ['La lumière du soleil levant', 'La nature de Bouddha exposée au moment de la mort', 'Un état de jhana profond', 'La vision de la Terre Pure'], correctAnswer: 1, explanation: 'La Lumière Claire (dharmata) est la nature de Bouddha qui se manifeste au moment de la mort — la reconnaître mène à la libération.', source: 'Bardo Thodol' },
  { id: 'q7-14', moduleId: 7, difficulty: 'moyen', question: 'Le karma est qualifié de "kusala" quand il est :', options: ['Neutre et sans effet', 'Salutaire, générateur de bien-être', 'Non-salutaire, générateur de souffrance', 'Instantanément rétribué'], correctAnswer: 1, explanation: 'Kusala karma est le karma salutaire, générateur de bien-être, né des racines de générosité, bienveillance et sagesse.', source: 'Tradition bouddhiste' },
  { id: 'q7-15', moduleId: 7, difficulty: 'moyen', question: 'Quel texte bouddhiste du Udana contient la description négative du Nirvana ?', options: ['Udana 1.1', 'Udana 8.3', 'Udana 5.5', 'Udana 3.10'], correctAnswer: 1, explanation: 'Udana 8.3 : "Il y a, moines, un non-né, non-devenu, non-créé, non-conditionné" — description du Nirvana.', source: 'Udana 8.3' },
  { id: 'q7-16', moduleId: 7, difficulty: 'difficile', question: 'Dans paticca-samuppada, qu\'est-ce que "nama-rupa" (4e lien) ?', options: ['Le nom et la couleur', 'Le corps-esprit (nom = mental, rupa = matière/corps)', 'La conscience et la perception', 'Les formations mentales et la volonté'], correctAnswer: 1, explanation: 'Nama-rupa désigne le complexe corps-esprit : nama (mental/psychique) et rupa (matière/corps physique).', source: 'Mahatanha-sankaya Sutta, MN 38' },
  { id: 'q7-17', moduleId: 7, difficulty: 'difficile', question: 'Selon l\'Anamataggasanyutta, qu\'est-il impossible de trouver pour le samsara ?', options: ['Son centre', 'Son début (pubb a koti na pannayati)', 'Sa fin', 'Sa cause première'], correctAnswer: 1, explanation: '"Pubb a koti na pannayati" — on ne peut trouver le commencement du samsara : il est sans début connaissable.', source: 'Anamataggasanyutta, SN 15.1' },
  { id: 'q7-18', moduleId: 7, difficulty: 'difficile', question: 'Padmasambhava est aussi connu sous le nom de :', options: ['Milarepa', 'Guru Rinpoche', 'Nagarjuna', 'Tilopa'], correctAnswer: 1, explanation: 'Padmasambhava (VIIIe s.) est connu sous le nom de Guru Rinpoche — il apporta le Vajrayana au Tibet.', source: 'Tradition Vajrayana tibétain' },
  { id: 'q7-19', moduleId: 7, difficulty: 'difficile', question: 'Karma Lingpa est associé à quel événement dans l\'histoire du Bardo Thodol ?', options: ['Il l\'écrivit au VIIIe siècle', 'Il le redécouvrit au XIVe siècle comme terma (trésor caché)', 'Il le traduisit en tibétain', 'Il le commenta au XVIIIe siècle'], correctAnswer: 1, explanation: 'Karma Lingpa redécouvrit le Bardo Thodol au XIVe siècle comme terma (trésor dharmique caché par Padmasambhava).', source: 'Tradition Nyingma' },
  { id: 'q7-20', moduleId: 7, difficulty: 'difficile', question: 'Les "formations mentales" (sankhara), 2e lien de paticca-samuppada, sont conditionnées par :', options: ['Vinnana (conscience)', 'Avijja (ignorance)', 'Phassa (contact)', 'Vedana (sensation)'], correctAnswer: 1, explanation: 'Avijja (ignorance) conditionne sankhara (formations mentales/volitions) — premier lien de la chaîne causale.', source: 'Sutta Pitaka' },

  // ── MODULE 8 : Les Enseignements du Bouddha ──────────────────
  { id: 'q8-1', moduleId: 8, difficulty: 'facile', question: 'Combien de versets contient le Dhammapada ?', options: ['108', '365', '423', '500'], correctAnswer: 2, explanation: 'Le Dhammapada contient 423 versets organisés en 26 chapitres thématiques.', source: 'Dhammapada' },
  { id: 'q8-2', moduleId: 8, difficulty: 'facile', question: 'Le premier verset du Dhammapada commence par :', options: ['"Toute vie est souffrance"', '"L\'esprit précède toutes les actions"', '"Soyez une lumière pour vous-mêmes"', '"La haine ne cesse jamais par la haine"'], correctAnswer: 1, explanation: '"Manopubbangama dhamma" — "L\'esprit précède toutes choses" — ouvre le Dhammapada.', source: 'Dhammapada 1' },
  { id: 'q8-3', moduleId: 8, difficulty: 'facile', question: 'Anatta signifie :', options: ['Impermanence', 'Souffrance', 'Non-soi', 'Karma'], correctAnswer: 2, explanation: 'Anatta (pali) ou anatman (sanskrit) désigne l\'absence d\'un soi permanent et indépendant.', source: 'Anattalakkhana Sutta, SN 22.59' },
  { id: 'q8-4', moduleId: 8, difficulty: 'facile', question: 'Anicca signifie :', options: ['Non-soi', 'Impermanence', 'Souffrance', 'Karma'], correctAnswer: 1, explanation: 'Anicca désigne l\'impermanence — tout phénomène conditionné est transitoire et changeant.', source: 'Dhammapada 277' },
  { id: 'q8-5', moduleId: 8, difficulty: 'facile', question: 'Le Kalama Sutta est considéré comme :', options: ['Le texte le plus difficile du bouddhisme', 'La charte de la libre enquête bouddhiste', 'Le guide de méditation principal', 'Le texte sur le karma'], correctAnswer: 1, explanation: 'Le Kalama Sutta (AN 3.65) est souvent appelé "la charte de la libre enquête" du bouddhisme.', source: 'Kalama Sutta, AN 3.65' },
  { id: 'q8-6', moduleId: 8, difficulty: 'facile', question: 'Le Dhammapada appartient à quel nikaya ?', options: ['Digha Nikaya', 'Majjhima Nikaya', 'Samyutta Nikaya', 'Khuddaka Nikaya'], correctAnswer: 3, explanation: 'Le Dhammapada fait partie du Khuddaka Nikaya (textes mineurs) du Sutta Pitaka.', source: 'Canon Pali' },
  { id: 'q8-7', moduleId: 8, difficulty: 'facile', question: 'L\'"interbeing" (inter-être) est un concept développé par :', options: ['Nagarjuna', 'Dogen', 'Thich Nhat Hanh', 'Dalai Lama'], correctAnswer: 2, explanation: 'Thich Nhat Hanh créa le terme "interbeing" pour exprimer de manière vivante l\'interdépendance (paticca-samuppada).', source: 'Thich Nhat Hanh' },
  { id: 'q8-8', moduleId: 8, difficulty: 'moyen', question: 'L\'Anattalakkhana Sutta enseigne le non-soi à travers l\'analyse des :', options: ['Quatre éléments', 'Cinq agrégats (khandhas)', 'Six bases des sens', 'Douze liens causaux'], correctAnswer: 1, explanation: 'Le Bouddha démontre l\'anatta en montrant qu\'aucun des cinq khandhas ne peut être identifié comme "soi".', source: 'Anattalakkhana Sutta, SN 22.59' },
  { id: 'q8-9', moduleId: 8, difficulty: 'moyen', question: 'La formule classique de l\'impermanence est : "Sabbe sankhara..." — quelle est la suite ?', options: ['...dukkha', '...anatta', '...anicca', '...suñña'], correctAnswer: 2, explanation: '"Sabbe sankhara anicca" — "Tous les composés sont impermanents" — Dhammapada 277.', source: 'Dhammapada 277' },
  { id: 'q8-10', moduleId: 8, difficulty: 'moyen', question: 'Le Kalama Sutta donne combien de critères pour évaluer un enseignement ?', options: ['Cinq', 'Sept', 'Dix', 'Douze'], correctAnswer: 2, explanation: 'Le Kalama Sutta donne dix types de sources à ne pas croire aveuglément, plus le critère éthique final.', source: 'Kalama Sutta, AN 3.65' },
  { id: 'q8-11', moduleId: 8, difficulty: 'moyen', question: '"Aniccanupassana" conduit à quelle progression selon le Canon Pali ?', options: ['Vers les jhanas profonds', 'Vers nibbida (désaffection) puis vimutti (libération)', 'Vers la renaissance dans les mondes célestes', 'Vers la pratique des préceptes'], correctAnswer: 1, explanation: 'La contemplation de l\'impermanence mène à nibbida (désaffection du conditionné) puis vimutti (libération).', source: 'Sutta Pitaka' },
  { id: 'q8-12', moduleId: 8, difficulty: 'moyen', question: 'La formule pali de l\'interdépendance "Imasming sati, idam hoti" signifie :', options: ['"Tout est souffrance"', '"Ceci étant, cela est"', '"L\'esprit précède tout"', '"La forme est vacuité"'], correctAnswer: 1, explanation: '"Imasming sati, idam hoti" — "Ceci étant, cela est" — formule de la production interdépendante.', source: 'SN 12.2' },
  { id: 'q8-13', moduleId: 8, difficulty: 'moyen', question: 'Le Bouddha enseigna le non-soi à qui en premier ?', options: ['Ananda', 'Kondanna et les cinq moines', 'Sariputta', 'Devadatta'], correctAnswer: 1, explanation: 'L\'Anattalakkhana Sutta fut enseigné aux cinq premiers moines (pañcavaggiya), peu après le premier discours.', source: 'Anattalakkhana Sutta, SN 22.59' },
  { id: 'q8-14', moduleId: 8, difficulty: 'moyen', question: 'Que signifie le terme "nibbida" dans le chemin de libération ?', options: ['Une joie spirituelle intense', 'La désaffection, le désenchantement envers le conditionné', 'Une forme de méditation', 'Un état de transe'], correctAnswer: 1, explanation: 'Nibbida est le désenchantement ou la désaffection envers les phénomènes conditionnés — étape vers la libération.', source: 'Tradition Theravada' },
  { id: 'q8-15', moduleId: 8, difficulty: 'moyen', question: 'Combien de chapitres contient le Dhammapada ?', options: ['10', '16', '26', '33'], correctAnswer: 2, explanation: 'Le Dhammapada est divisé en 26 vaggas (chapitres), de Yamakavagga (chapître des paires) à Brahmanavagga.', source: 'Dhammapada' },
  { id: 'q8-16', moduleId: 8, difficulty: 'difficile', question: 'Le critère positif du Kalama Sutta pour adopter un enseignement est :', options: ['Qu\'il soit approuvé par un texte sacré', 'Qu\'il soit salutaire, sans reproche et conduise au bonheur selon les sages', 'Qu\'il soit enseigné par un maître réalisé', 'Qu\'il corresponde à l\'expérience de la communauté'], correctAnswer: 1, explanation: 'Critère positif du Kalama Sutta : "ces choses sont salutaires, sans reproche, louées par les sages, conduisent au bonheur."', source: 'Kalama Sutta, AN 3.65' },
  { id: 'q8-17', moduleId: 8, difficulty: 'difficile', question: 'Dans l\'Anattalakkhana Sutta, pourquoi la forme (rupa) n\'est-elle pas "soi" ?', options: ['Car elle est trop grosse pour être soi', 'Car si elle était soi, on pourrait décider qu\'elle soit telle ou telle', 'Car elle appartient à la terre', 'Car le Bouddha l\'a décrété ainsi'], correctAnswer: 1, explanation: '"Si rupa était soi, on pourrait déclarer : que ma forme soit ainsi, ne soit pas ainsi" — mais ce n\'est pas possible.', source: 'Anattalakkhana Sutta, SN 22.59' },
  { id: 'q8-18', moduleId: 8, difficulty: 'difficile', question: 'L\'impermanence des formations se dit en pali :', options: ['Sabbe dhamma anatta', 'Sabbe sankhara anicca', 'Sabbe bhava dukkha', 'Sabbe citta vinnana'], correctAnswer: 1, explanation: '"Sabbe sankhara anicca" (Dhammapada 277) — tous les composés/formations sont impermanents.', source: 'Dhammapada 277' },
  { id: 'q8-19', moduleId: 8, difficulty: 'difficile', question: 'Quel texte du Canon Pali contient la première formulation complète d\'anatta ?', options: ['Dhammacakkappavattana Sutta', 'Anattalakkhana Sutta (SN 22.59)', 'Satipatthana Sutta', 'Metta Sutta'], correctAnswer: 1, explanation: 'L\'Anattalakkhana Sutta (SN 22.59) est le texte où le Bouddha expose systématiquement la doctrine du non-soi.', source: 'Anattalakkhana Sutta, SN 22.59' },
  { id: 'q8-20', moduleId: 8, difficulty: 'difficile', question: 'La formule "sabbe dhamma anatta" (tous les phénomènes sont non-soi) se distingue de "sabbe sankhara anicca" car :', options: ['Elles sont identiques', '"Dhamma" inclut aussi le Nirvana, non conditionné, dans l\'anatta', '"Sankhara" est plus universel que "dhamma"', '"Dhamma" exclut les états mentaux'], correctAnswer: 1, explanation: '"Sabbe dhamma anatta" inclut le Nirvana (non conditionné) dans l\'anatta, alors que sankhara ne désigne que le conditionné.', source: 'Dhammapada 279' },

  // ── MODULE 9 : Éthique Bouddhiste ────────────────────────────
  { id: 'q9-1', moduleId: 9, difficulty: 'facile', question: 'Combien de préceptes bouddhistes de base y a-t-il pour les laïcs ?', options: ['Trois', 'Cinq', 'Eight', 'Dix'], correctAnswer: 1, explanation: 'Les cinq préceptes (pañca-sila) sont l\'engagement éthique fondamental pour les bouddhistes laïcs.', source: 'Tradition bouddhiste' },
  { id: 'q9-2', moduleId: 9, difficulty: 'facile', question: 'Que signifie ahimsa ?', options: ['Méditation profonde', 'Non-violence / non-nuisance', 'Générosité', 'Sagesse'], correctAnswer: 1, explanation: 'Ahimsa (sanskrit/pali : avihimsa) signifie non-nuisance ou non-violence envers tous les êtres.', source: 'Tradition bouddhiste' },
  { id: 'q9-3', moduleId: 9, difficulty: 'facile', question: 'Dana signifie :', options: ['Discipline', 'Générosité / le don', 'Méditation', 'Sagesse'], correctAnswer: 1, explanation: 'Dana (pali et sanskrit) désigne la générosité, le don — première des pratiques bouddhistes.', source: 'Tradition bouddhiste' },
  { id: 'q9-4', moduleId: 9, difficulty: 'facile', question: 'Le premier précepte bouddhiste porte sur :', options: ['Le mensonge', 'Le vol', 'Ne pas prendre la vie', 'L\'intoxication'], correctAnswer: 2, explanation: 'Premier précepte : "Panatipata veramani sikkhapadam samadiyami" — s\'abstenir de prendre la vie.', source: 'Pañca-sila' },
  { id: 'q9-5', moduleId: 9, difficulty: 'facile', question: 'Upekkha est :', options: ['La compassion', 'La joie partagée', 'L\'équanimité', 'L\'amour bienveillant'], correctAnswer: 2, explanation: 'Upekkha (pali) ou upeksha (sanskrit) est l\'équanimité — quatrième brahmavihara.', source: 'Tradition bouddhiste' },
  { id: 'q9-6', moduleId: 9, difficulty: 'facile', question: 'Karuna signifie :', options: ['Amour bienveillant', 'Compassion', 'Joie', 'Équanimité'], correctAnswer: 1, explanation: 'Karuna désigne la compassion — le désir que tous les êtres soient libérés de la souffrance.', source: 'Tradition bouddhiste' },
  { id: 'q9-7', moduleId: 9, difficulty: 'facile', question: 'Les jours d\'Uposatha sont des jours :', options: ['De fête bouddhiste', 'D\'observation renforcée des préceptes', 'De jeûne total', 'De pèlerinage'], correctAnswer: 1, explanation: 'Les jours d\'Uposatha, les bouddhistes observent les Huit Préceptes et les moines récitent le Patimokkha.', source: 'Tradition bouddhiste' },
  { id: 'q9-8', moduleId: 9, difficulty: 'moyen', question: 'Quelles sont les quatre brahmaviharas dans l\'ordre traditionnel ?', options: ['Karuna, Metta, Mudita, Upekkha', 'Metta, Karuna, Mudita, Upekkha', 'Upekkha, Metta, Karuna, Mudita', 'Mudita, Karuna, Metta, Upekkha'], correctAnswer: 1, explanation: 'L\'ordre traditionnel des brahmaviharas est : metta, karuna, mudita, upekkha.', source: 'Tradition bouddhiste' },
  { id: 'q9-9', moduleId: 9, difficulty: 'moyen', question: 'Comment les Cinq Préceptes sont-ils perçus dans le bouddhisme ?', options: ['Comme des commandements divins', 'Comme des règles monastiques', 'Comme un entraînement volontairement adopté pour sa propre purification', 'Comme des lois civiles'], correctAnswer: 2, explanation: 'Les préceptes sont sikkha-pada — un entraînement librement adopté, non des commandements imposés.', source: 'Tradition bouddhiste' },
  { id: 'q9-10', moduleId: 9, difficulty: 'moyen', question: 'Quel est l\'"ennemi proche" d\'upekkha (équanimité) ?', options: ['La haine', 'La passion', 'L\'indifférence froide', 'La tristesse'], correctAnswer: 2, explanation: 'L\'"ennemi proche" d\'upekkha est l\'indifférence froide qui ressemble à l\'équanimité mais en est la perversion.', source: 'Tradition bouddhiste' },
  { id: 'q9-11', moduleId: 9, difficulty: 'moyen', question: 'La qualité du don (dana) qui génère le plus de mérite est :', options: ['La quantité donnée', 'Donner avec joie, sans attente et sans orgueil', 'Donner aux moines uniquement', 'Donner en public pour l\'exemple'], correctAnswer: 1, explanation: 'La qualité intérieure du don importe : donner avec joie, sans attente de retour et sans orgueil génère le plus de mérite.', source: 'Tradition bouddhiste' },
  { id: 'q9-12', moduleId: 9, difficulty: 'moyen', question: 'Le cinquième précepte porte sur :', options: ['Le mensonge', 'La sexualité', 'Les substances intoxicantes', 'Le vol'], correctAnswer: 2, explanation: 'Cinquième précepte : "Surameraya-majja-pamadatthana veramani" — s\'abstenir de substances intoxicantes.', source: 'Pañca-sila' },
  { id: 'q9-13', moduleId: 9, difficulty: 'moyen', question: 'Comment la tradition bouddhiste justifie-t-elle l\'ahimsa universelle envers tous les êtres ?', options: ['Car tous les êtres sont divins', 'Car les êtres ont été nos parents dans des vies passées', 'Car cela améliore le karma', 'Car c\'est la loi naturelle'], correctAnswer: 1, explanation: 'Le Brahmajala Sutta enseigne que les êtres ont été nos parents dans des vies passées — base de l\'ahimsa universelle.', source: 'Brahmajala Sutta' },
  { id: 'q9-14', moduleId: 9, difficulty: 'moyen', question: 'La pratique de karuna bhavana commence par :', options: ['Reconnaître un ennemi et cultiver la compassion', 'Reconnaître un être qui souffre et souhaiter sa libération', 'Réciter des mantras de compassion', 'Pratiquer l\'équanimité d\'abord'], correctAnswer: 1, explanation: 'Karuna bhavana commence par reconnaître un être souffrant et cultiver : "Que tu sois libéré de la souffrance."', source: 'Tradition bouddhiste' },
  { id: 'q9-15', moduleId: 9, difficulty: 'moyen', question: 'Dana développe quelle qualité mentale selon le Danapathasuttam ?', options: ['La concentration', 'Le désintachement (vairagya) et affaiblit l\'avarice', 'La mémorisation des suttas', 'La capacité méditatives'], correctAnswer: 1, explanation: 'Dana développe le détachement et affaiblit l\'avarice (macchariya) — deux racines de la souffrance.', source: 'Danapathasuttam, AN 8.31' },
  { id: 'q9-16', moduleId: 9, difficulty: 'difficile', question: 'L\'upekkha du quatrième jhana est décrite comme :', options: ['Un état de joie intense', 'Pureté de l\'équanimité et de l\'attention, ni plaisir ni douleur', 'Concentration sans contenu', 'Absence totale de conscience'], correctAnswer: 1, explanation: 'Quatrième jhana : "upekkhaparisuddhi sati-parisuddha" — pureté d\'équanimité et d\'attention, adukkhamasukha.', source: 'Samaññaphala Sutta, DN 2' },
  { id: 'q9-17', moduleId: 9, difficulty: 'difficile', question: 'Les Huit Préceptes ajoutent aux cinq lesquels ?', options: ['Végétarisme et célibat', 'Abstention des divertissements mondains et des repas après midi', 'Silence total et méditation obligatoire', 'Port de robes monastiques et collecte d\'aumônes'], correctAnswer: 1, explanation: 'Les Huit Préceptes ajoutent : s\'abstenir des repas après midi, des spectacles/musique, des parures, et du luxe.', source: 'Tradition bouddhiste' },
  { id: 'q9-18', moduleId: 9, difficulty: 'difficile', question: 'La formule pali du premier précepte est :', options: ['Musavada veramani sikkhapadam samadiyami', 'Panatipata veramani sikkhapadam samadiyami', 'Adinnadana veramani sikkhapadam samadiyami', 'Kamesumicchacara veramani sikkhapadam samadiyami'], correctAnswer: 1, explanation: '"Panatipata veramani sikkhapadam samadiyami" — "Je m\'entraîne à m\'abstenir de prendre la vie."', source: 'Pañca-sila' },
  { id: 'q9-19', moduleId: 9, difficulty: 'difficile', question: 'Les "quatre ressources" (paccaya) du moine sont :', options: ['Méditation, étude, service, prière', 'Nourriture reçue en aumône, robes, logement simple, médicaments', 'Silence, solitude, abstinence, obéissance', 'Temple, maître, textes, pratique'], correctAnswer: 1, explanation: 'Les quatre paccaya (ressources) : nourriture reçue (pindapata), robes, logement et médicaments.', source: 'Vinaya Pitaka' },
  { id: 'q9-20', moduleId: 9, difficulty: 'difficile', question: 'Selon la tradition, quel est l\'"ennemi lointain" de la compassion (karuna) ?', options: ['L\'orgueil', 'La peur', 'La cruauté', 'L\'ignorance'], correctAnswer: 2, explanation: 'L\'"ennemi lointain" de karuna est la cruauté (himsá) — l\'opposé direct de la compassion.', source: 'Tradition bouddhiste' },

  // ── MODULE 10 : Bouddhisme Contemporain ─────────────────────
  { id: 'q10-1', moduleId: 10, difficulty: 'facile', question: 'Thich Nhat Hanh fut originaire de quel pays ?', options: ['Corée', 'Japon', 'Vietnam', 'Thaïlande'], correctAnswer: 2, explanation: 'Thich Nhat Hanh (1926-2022) était un maître Zen vietnamien, pionnier du bouddhisme engagé.', source: 'Biographie de Thich Nhat Hanh' },
  { id: 'q10-2', moduleId: 10, difficulty: 'facile', question: 'Quel prix le 14e Dalaï-Lama reçut-il en 1989 ?', options: ['Prix Nobel de Littérature', 'Prix Nobel de la Paix', 'Prix Sakharov', 'Médaille Présidentielle de la Liberté'], correctAnswer: 1, explanation: 'Le 14e Dalaï-Lama reçut le Prix Nobel de la Paix en 1989 pour son engagement pour la non-violence.', source: 'Biographie du Dalaï-Lama' },
  { id: 'q10-3', moduleId: 10, difficulty: 'facile', question: 'MBSR signifie :', options: ['Mindful Buddhism Stress Response', 'Mindfulness-Based Stress Reduction', 'Meditative Buddhist Spiritual Ritual', 'Modern Buddhist Secular Retreat'], correctAnswer: 1, explanation: 'MBSR (Mindfulness-Based Stress Reduction) est le protocole clinique créé par Jon Kabat-Zinn à l\'Université du Massachusetts.', source: 'Jon Kabat-Zinn, UMASS' },
  { id: 'q10-4', moduleId: 10, difficulty: 'facile', question: 'Où se trouve le Village des Pruniers de Thich Nhat Hanh ?', options: ['Vietnam', 'États-Unis', 'Dordogne, France', 'Allemagne'], correctAnswer: 2, explanation: 'Le Village des Pruniers (Plum Village) est situé en Dordogne, France — fondé par Thich Nhat Hanh en 1982.', source: 'Plum Village' },
  { id: 'q10-5', moduleId: 10, difficulty: 'facile', question: 'Matthieu Ricard est :', options: ['Un moine tibétain né au Tibet', 'Un moine bouddhiste français, docteur en biologie moléculaire', 'Un professeur de méditation laïc', 'Le fondateur de la Terre Pure en France'], correctAnswer: 1, explanation: 'Matthieu Ricard est un moine bouddhiste français, ancien biologiste, disciple de Dilgo Khyentse Rinpoche.', source: 'Biographie de Matthieu Ricard' },
  { id: 'q10-6', moduleId: 10, difficulty: 'facile', question: 'Jon Kabat-Zinn créa le MBSR dans quelle institution ?', options: ['Harvard', 'Stanford', 'Université du Massachusetts Medical School', 'MIT'], correctAnswer: 2, explanation: 'Jon Kabat-Zinn développa le MBSR à l\'Université du Massachusetts Medical School à la fin des années 1970.', source: 'Histoire du MBSR' },
  { id: 'q10-7', moduleId: 10, difficulty: 'facile', question: 'Qui fonda la tradition Shambhala en Amérique du Nord ?', options: ['Thich Nhat Hanh', 'Chogyam Trungpa', 'D.T. Suzuki', 'Ajahn Chah'], correctAnswer: 1, explanation: 'Chogyam Trungpa Rinpoche fonda la tradition Shambhala au Canada puis aux États-Unis dans les années 1970.', source: 'Histoire du bouddhisme occidental' },
  { id: 'q10-8', moduleId: 10, difficulty: 'moyen', question: 'Le bouddhisme engagé fut développé par Thich Nhat Hanh en réponse à :', options: ['La montée du capitalisme', 'La guerre du Vietnam et ses souffrances', 'La crise environnementale', 'La persécution religieuse'], correctAnswer: 1, explanation: 'Thich Nhat Hanh développa le bouddhisme engagé pendant et après la guerre du Vietnam pour répondre aux souffrances réelles.', source: 'Biographie de Thich Nhat Hanh' },
  { id: 'q10-9', moduleId: 10, difficulty: 'moyen', question: 'L\'Ordre de l\'Inter-Être (Tiep Hien) fut fondé en :', options: ['1954', '1966', '1975', '1982'], correctAnswer: 1, explanation: 'Thich Nhat Hanh fonda l\'Ordre de l\'Inter-Être (Tiep Hien) en 1966 avec 14 préceptes actualisés.', source: 'Biographie de Thich Nhat Hanh' },
  { id: 'q10-10', moduleId: 10, difficulty: 'moyen', question: 'Les Dialogues Mind and Life entre le Dalaï-Lama et des neuroscientifiques débutèrent en :', options: ['1975', '1987', '1995', '2000'], correctAnswer: 1, explanation: 'Les dialogues Mind and Life entre le Dalaï-Lama et des neuroscientifiques commencèrent en 1987.', source: 'Mind and Life Institute' },
  { id: 'q10-11', moduleId: 10, difficulty: 'moyen', question: 'Richard Davidson découvrit que la méditation affecte positivement quelle zone du cerveau ?', options: ['Le lobe temporal gauche', 'Le cortex préfrontal gauche et la réduction de l\'activité amygdalienne', 'Le cervelet', 'Le corps calleux'], correctAnswer: 1, explanation: 'Davidson montra : augmentation du cortex préfrontal gauche (émotions positives) et réduction de l\'amygdale (stress).', source: 'Richard Davidson, UW-Madison' },
  { id: 'q10-12', moduleId: 10, difficulty: 'moyen', question: 'B.R. Ambedkar se convertit au bouddhisme pour :', options: ['Raisons philosophiques personnelles', 'Offrir une alternative à l\'ordre social des castes aux intouchables d\'Inde', 'Suivre son maître spirituel', 'Raisons politiques contre le Congrès'], correctAnswer: 1, explanation: 'Ambedkar convertit en 1956 avec 500 000 partisans, voyant dans le Dharma une libération de l\'oppression des castes.', source: 'Biographie de B.R. Ambedkar' },
  { id: 'q10-13', moduleId: 10, difficulty: 'moyen', question: 'Stephen Batchelor est associé à :', options: ['La tradition Theravada birmane', 'Le bouddhisme laïc, "Buddhism Without Beliefs"', 'Le Vajrayana tibétain', 'La tradition Zen Soto'], correctAnswer: 1, explanation: 'Stephen Batchelor développa le "secular Buddhism" (bouddhisme laïc) avec "Buddhism Without Beliefs" (1997).', source: 'Stephen Batchelor, "Buddhism Without Beliefs"' },
  { id: 'q10-14', moduleId: 10, difficulty: 'moyen', question: 'MBCT (Mindfulness-Based Cognitive Therapy) est particulièrement efficace pour :', options: ['Les douleurs physiques aiguës', 'La prévention des rechutes dépressives', 'Les troubles du sommeil', 'Le trouble bipolaire'], correctAnswer: 1, explanation: 'MBCT fut spécifiquement développé pour réduire le risque de rechute dans la dépression récurrente.', source: 'Segal, Williams, Teasdale - MBCT' },
  { id: 'q10-15', moduleId: 10, difficulty: 'moyen', question: 'Joanna Macy développa quel type de pratique pour répondre à la crise écologique ?', options: ['La méditation vipassana environnementale', 'Le "Travail qui Relie"', 'Le tonglen appliqué à la nature', 'Le bouddhisme vert'], correctAnswer: 1, explanation: 'Joanna Macy développa le "Work That Reconnects" (Travail qui Relie) pour répondre à la douleur écologique.', source: 'Joanna Macy, "World as Lover, World as Self"' },
  { id: 'q10-16', moduleId: 10, difficulty: 'difficile', question: 'D.T. Suzuki fut pionnier de la diffusion de quel courant bouddhiste en Occident ?', options: ['Theravada', 'Zen', 'Vajrayana tibétain', 'Terre Pure'], correctAnswer: 1, explanation: 'Daisetz Teitaro Suzuki (1870-1966) popularisa le Zen en Occident à travers ses nombreux écrits en anglais.', source: 'Histoire du bouddhisme occidental' },
  { id: 'q10-17', moduleId: 10, difficulty: 'difficile', question: 'Sulak Sivaraksa est un acteur du bouddhisme engagé originaire de :', options: ['Vietnam', 'Cambodge', 'Thaïlande', 'Inde'], correctAnswer: 2, explanation: 'Sulak Sivaraksa est un intellectuel et activiste thaïlandais, cofondateur du mouvement bouddhiste engagé en Asie.', source: 'Histoire du bouddhisme engagé' },
  { id: 'q10-18', moduleId: 10, difficulty: 'difficile', question: 'Sara Lazar de Harvard montra que la méditation à long terme :', options: ['Réduit la taille du cerveau', 'Épaissit le cortex préfrontal et l\'insula', 'Augmente les ondes delta', 'Modifie la structure de l\'hippocampe uniquement'], correctAnswer: 1, explanation: 'Sara Lazar (Harvard) démontra que la pratique à long terme épaissit le cortex préfrontal et l\'insula (conscience corporelle).', source: 'Sara Lazar, Harvard Medical School' },
  { id: 'q10-19', moduleId: 10, difficulty: 'difficile', question: 'Maha Ghosananda est une figure du bouddhisme engagé originaire de :', options: ['Thaïlande', 'Vietnam', 'Cambodge', 'Birmanie'], correctAnswer: 2, explanation: 'Maha Ghosananda (1929-2007), surnommé "le Gandhi cambodgien", mena des marches de paix après le génocide Khmer Rouge.', source: 'Histoire du bouddhisme engagé' },
  { id: 'q10-20', moduleId: 10, difficulty: 'difficile', question: 'Le "bouddhisme laïc" de Stephen Batchelor propose :', options: ['Un bouddhisme sans méditation', 'Une approche empirique, agnostique sur la renaissance, centrée sur la pratique du chemin', 'Un bouddhisme athée qui rejette tous les textes', 'Un bouddhisme uniquement psychologique'], correctAnswer: 1, explanation: 'Batchelor propose une approche empirique et agnostique : ni affirmer ni nier la renaissance, pratiquer le chemin ici et maintenant.', source: 'Stephen Batchelor, "Buddhism Without Beliefs"' },
];

export default quizQuestions;
